const base=path.resolve(os.tmpdir(),'stars-second-chance-dm-confirmation'),roots=[]
afterEach(async()=>{for(const root of roots.splice(0)){if(path.dirname(root)!==base||!path.basename(root).startsWith('room-'))throw Error('Cleanup outside this fixture root');await fs.rm(root,{recursive:true,force:true,maxRetries:4,retryDelay:20})}})
async function fixture(kind='normal',mutate=()=>{}){
 const docs=structuredClone(kind==='critical'?criticalFixture:normalFixture),receipt=Object.values(docs.combat.secondChanceAttacks)[0],roomId=docs.characters.characters[0].roomId,memberId=receipt.hostControllerMemberId,rollerId=receipt.attack.rollerControllerMemberId
 await fs.mkdir(base,{recursive:true});const root=await fs.mkdtemp(path.join(base,'room-'));roots.push(root);const stateRoot=path.join(root,'rooms',roomId),lobbyRoot=path.join(root,'lobby');await fs.mkdir(stateRoot,{recursive:true});await fs.mkdir(lobbyRoot,{recursive:true})
 const tokens={dm:randomBytes(32).toString('base64url'),player:randomBytes(32).toString('base64url'),spectator:randomBytes(32).toString('base64url')},hash=value=>createHash('sha256').update(value).digest('hex')
 await fs.writeFile(path.join(lobbyRoot,roomId+'.json'),JSON.stringify({id:roomId,host:{memberId,roomTokenHash:hash(tokens.dm)},players:[{memberId:rollerId,role:'player',roomTokenHash:hash(tokens.player)},{memberId:'spectator',role:'spectator',roomTokenHash:hash(tokens.spectator)}]}))
 mutate(docs,receipt)
 for(const[name,value]of Object.entries(docs))if(value!=null)await fs.writeFile(path.join(stateRoot,name+'.json'),JSON.stringify(value))
 const ctx={stateRoot:root,lobbyRoot,imageRoot:root,legacyStateRoot:root,legacyImageRoot:root,quarantineRoot:root,snapshotRoot:root,eventClients:new Map(),eventBacklog:new Map(),eventSequences:new Map(),rateLimits:new Map()},read=async name=>{try{return JSON.parse(await fs.readFile(path.join(stateRoot,name+'.json'),'utf8'))}catch(error){if(error.code==='ENOENT')return null;throw error}}
 const request=kind==='critical'?Object.values(receipt.pendingCriticalDiceRequests)[0]:null,action={id:'auth-confirm-'+randomBytes(8).toString('hex'),mapId:receipt.attack.mapId,combatId:receipt.attack.combatId,actorTokenId:receipt.attack.rollerTokenId,characterId:receipt.attack.rollerCharacterId,type:'dnd5e-second-chance',status:'pending',sourceMode:'player',roomMemberId:'forged',round:1,initiativeIndex:0,seq:1,updatedAt:1,secondChance:kind==='critical'?{phase:'confirm-critical-roll',attackReceiptId:receipt.attack.id,supplementRequestId:request.id,values:[6]}:{phase:'confirm-roll',attackReceiptId:receipt.attack.id,rollRequestId:receipt.rollRequestId,value:1}}
 async function append(next=action,role='dm'){
  const actor=role==='dm'?memberId:role==='player'?rollerId:'spectator',token=role==='unauthenticated'?'invalid-token':tokens[role]
  const req=Readable.from([Buffer.from(JSON.stringify({action:next}))]);Object.assign(req,{method:'POST',headers:{'x-stars-member':actor,'x-stars-room-token':token,'x-stars-protocol':String(SHARED_PROTOCOL_VERSION)},socket:{remoteAddress:'fixture-local'}})
  const res={status:0,body:'',headers:{},setHeader(k,v){this.headers[k]=v},getHeader(k){return this.headers[k]},writeHead(s,h){this.status=s;Object.assign(this.headers,h??{})},end(b){this.body=String(b??'')}}
  expect(await handleSharedApi(req,res,new URL('http://localhost/api/state/player-action-requests/append?room='+roomId),ctx)).toBe(true);return{status:res.status,payload:JSON.parse(res.body)}
 }
 return{docs,receipt,memberId,rollerId,action,append,read}
}
it.each(['normal','critical'])('actual authenticated DM appends only a locked original-roller %s confirmation and idempotently replays the same command',async kind=>{
 const f=await fixture(kind),before=await f.read('combat'),response=await f.append();expect(response.status,JSON.stringify(response)).toBe(200)
 const queue=await f.read('player-action-requests'),saved=queue.requests.find(row=>row.id===f.action.id);expect(saved).toMatchObject({roomMemberId:f.memberId,sourceMode:'dm',secondChance:f.action.secondChance});expect(saved.roomMemberId).not.toBe('forged');expect(await f.read('combat')).toEqual(before)
 expect((await f.append({...f.action,updatedAt:2,seq:2,roomMemberId:'another-forged'})).status).toBe(200);expect((await f.read('player-action-requests')).requests.filter(row=>row.id===f.action.id)).toHaveLength(1)
 const conflicting={...f.action,secondChance:kind==='normal'?{...f.action.secondChance,value:2}:{...f.action.secondChance,values:[1]}};expect((await f.append(conflicting)).status).toBe(403)
})
for(const role of['player','spectator','unauthenticated'])it('rejects final confirmation from the real '+role+' transport principal',async()=>{const f=await fixture(),before=await f.read('player-action-requests');expect((await f.append({...f.action,sourceMode:'dm',roomMemberId:f.memberId},role)).status).toBe(403);expect(await f.read('player-action-requests')).toEqual(before)})
const boundaries={
 'original raw not yet locked':(d,r)=>delete r.rollerD20,
 'another DM controller':(d,r)=>r.hostControllerMemberId='different-host',
 'stale defender turn':(d,r)=>d.combat.dnd5eTurnEconomyByToken[r.attack.targetTokenId].turnKey='another-turn',
 'stale character version':d=>d.characters._sync.revision++,
 'stale map version':d=>d.maps._sync.revision++,
 'changed geometry version':d=>d['map-geometry']={_sync:{schemaVersion:1,revision:1,writerId:'fixture-dm',writtenAt:1}},
 'attack no longer pending':(d,r)=>r.attack.phase='damage-committed',
 'already confirmed':(d,r)=>r.rollerConfirmation={authenticatedMemberId:r.hostControllerMemberId,rollRequestId:r.rollRequestId,rawValue:r.rollerD20.value,value:1}
}
for(const[label,mutate]of Object.entries(boundaries))it('rejects '+label+' without appending or touching original HP/resource state',async()=>{const f=await fixture('normal',mutate),before={queue:await f.read('player-action-requests'),characters:await f.read('characters'),combat:await f.read('combat')};expect((await f.append()).status).toBe(403);expect(await f.read('player-action-requests')).toEqual(before.queue);expect(await f.read('characters')).toEqual(before.characters);expect(await f.read('combat')).toEqual(before.combat)})
